localExtraFields.tn.push(['orderNumber','Номер заказа / заявки'],['orderDate','Дата заказа / заявки','date'],['rerouteContact','Контакты для переадресовки'],['loadingArrival','Прибытие на погрузку','datetime-local'],['loadingDeparture','Убытие с погрузки','datetime-local'],['unloadingArrival','Прибытие на выгрузку','datetime-local'],['unloadingDeparture','Убытие с выгрузки','datetime-local'],['loadingPosition','Должность лица, осуществившего погрузку'],['deliveryPosition','Должность получателя'],['driverAccept','Водитель, принявший груз: ФИО'],['driverDeliver','Водитель, сдавший груз: ФИО'],['deliveryMass','Масса груза при выдаче, кг'],['deliveryPlaces','Количество мест при выдаче'],['penalty','Расчёт и размер штрафа']);
localExtraFields.ttn.push(['loadingArrival','Прибытие на погрузку','datetime-local'],['loadingDeparture','Убытие с погрузки','datetime-local'],['unloadingArrival','Прибытие на выгрузку','datetime-local'],['unloadingDeparture','Убытие с выгрузки','datetime-local'],['loadingMethod','Способ погрузки'],['unloadingMethod','Способ разгрузки'],['transportNotes','Прочие транспортные сведения']);

const docItemTypes=['invoice','act','vat','upd','torg12','ttn',...Object.keys(DOC_NEW).filter(id=>DOC_NEW[id].items)];
const docTransport=['tn','ttn','waybill','order','contract'];
function localDocumentKey(){return 'transera-local-documents:'+String(currentUser?.email||'guest').toLowerCase();}
function localDocumentRead(){try{const x=JSON.parse(localStorage.getItem(localDocumentKey())||'[]');return Array.isArray(x)?x:[];}catch{return [];}}
function localDocumentWrite(items){localStorage.setItem(localDocumentKey(),JSON.stringify(items));}
function localDocumentSave(data){if(!data)return;const rows=localDocumentRead(),i=rows.findIndex(x=>x.id===data.id);if(i<0)rows.unshift(data);else rows[i]=data;localDocumentWrite(rows);localDocumentId=data.id;docDirty=false;docPending=null;docStatus('Черновик сохранён на устройстве');}
function docStatus(text,error=false){const el=document.getElementById('doc-save-status');if(el){el.textContent=text;el.classList.toggle('doc-error',error);}}
function docLabel(type){return localDocumentTypes.find(x=>x[0]===type)?.[1]||'Документ';}
function docDate(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
// Structured party records preserve legacy draft fields and directory IDs.
function docPartyRoles(type){
 if(DOC_NEW[type])return DOC_NEW[type].roles;
 const labels={tn:['Грузоотправитель','Грузополучатель'],ttn:['Грузоотправитель','Грузополучатель'],waybill:['Владелец транспортного средства'],invoice:['Поставщик / получатель оплаты','Покупатель / плательщик'],act:['Исполнитель','Заказчик'],upd:['Продавец','Покупатель'],vat:['Продавец','Покупатель'],torg12:['Поставщик','Покупатель'],reconcile:['Ваша организация','Контрагент'],order:['Грузоотправитель','Заказчик'],contract:['Перевозчик / исполнитель','Заказчик']};
 const names=labels[type]||['Исполнитель','Заказчик'],roles=[['seller',names[0]]];if(names[1])roles.push(['buyer',names[1]]);
 if(['tn','ttn','order'].includes(type))roles.push(['carrier','Перевозчик']);
 if(type==='tn')roles.push(['forwarder','Заказчик организации перевозки (при наличии)']);
 if(['vat','upd','torg12'].includes(type))roles.push(['shipper','Грузоотправитель (при наличии)'],['consignee','Грузополучатель (при наличии)']);
 if(type==='order')roles.push(['consignee','Грузополучатель']);
 if(['ttn','torg12'].includes(type))roles.push(['payer','Плательщик (если отличается от покупателя)']);
 return roles;
}
function docPartyKeys(role,type){const bank=role==='seller'&&type==='invoice';return {name:role,inn:role+'Inn',kpp:role+'Kpp',ogrn:role+'Ogrn',address:role+'Address',postalAddress:role+'PostalAddress',phone:role+'Phone',email:role+'Email',sign:role+'Sign',basis:role+'Basis',bank:bank?'bank':role+'Bank',bik:bank?'bik':role+'Bik',account:bank?'account':role+'Account',correspondent:bank?'correspondent':role+'Correspondent',legacy:role+'Details',...(DOC_NEW[type]?{identity:role+'Identity',issuedBy:role+'IssuedBy',issuedOn:role+'IssuedOn',birthDate:role+'BirthDate',birthPlace:role+'BirthPlace',personType:role+'PersonType'}:{})};}
function docPartyBlock(role,label,d){const k=docPartyKeys(role,localDocumentType),opts=localPartyOptions();const input=(key,title,kind)=>docInput([k[key],title,kind],d[k[key]]);const bankRequired=['invoice','contract','order'].includes(localDocumentType);const bankAllowed=!['tn','ttn','vat','upd','waybill'].includes(localDocumentType);
 return '<fieldset class="doc-party-block" data-doc-party="'+role+'"><legend>'+esc(label)+'</legend><label class="doc-party-selector">Подставить из справочника<select data-doc-party-fill="'+role+'"><option value="">Заполнить вручную или выбрать организацию</option>'+opts+'</select></label><div class="fields">'+input('name','Наименование организации / ФИО')+input('address','Юридический адрес / адрес регистрации')+input('inn','ИНН')+input('kpp','КПП (для организации)')+input('ogrn','ОГРН / ОГРНИП')+input('postalAddress','Почтовый адрес (если отличается)')+input('phone','Телефон')+input('email','Электронная почта')+'</div>'+(DOC_NEW[localDocumentType]?bizPartyIdentity(role,d):'')+(bankAllowed?'<details class="doc-party-bank" '+(bankRequired?'open':'')+'><summary>Банковские реквизиты'+(bankRequired?'':' (при необходимости)')+'</summary><div class="fields">'+input('bank','Наименование банка')+input('bik','БИК')+input('account','Расчётный счёт')+input('correspondent','Корреспондентский счёт')+'</div></details>':'')+'<details class="doc-party-bank"><summary>Подписант и основание полномочий</summary><div class="fields">'+input('sign','Подписант: должность, ФИО')+input('basis','Действует на основании')+'</div></details>'+(d[k.legacy]?'<details class="doc-party-legacy"><summary>Реквизиты из ранее сохранённого черновика</summary>'+docInput([k.legacy,'Ранее сохранённая строка реквизитов','textarea'],d[k.legacy])+'<p class="doc-hint">Старая строка сохранена. Разнесите данные по отдельным полям; ранее введённый текст также будет выведен в документ.</p></details>':'')+'</fieldset>';
}
function docNormalizeParties(data){const d={...data};for(const [role] of docPartyRoles(d.type)){const k=docPartyKeys(role,d.type);if(d[k.inn]&&/^\d+\s*\/\s*\d+$/.test(d[k.inn])){const [inn,kpp]=d[k.inn].split('/').map(v=>v.trim());d[k.inn]=inn;if(!d[k.kpp])d[k.kpp]=kpp;}}
 if(d.type==='order'){d.seller=d.seller||d.shipper||'';d.shipper=d.seller;d.customerSign=d.buyerSign||d.customerSign;d.customerBasis=d.buyerBasis||d.customerBasis;}
 return d;
}
function docFillParty(role,id){const party=localDirectoryRead().records.find(x=>x.id===id),form=document.getElementById('local-document-form');if(!party||!form)return;const k=docPartyKeys(role,localDocumentType),map={name:party.name,inn:party.inn,kpp:party.kpp,ogrn:party.ogrn,address:party.address,postalAddress:party.postalAddress,phone:party.phone,email:party.email,sign:party.director,basis:party.basis,bank:party.bank,bik:party.bik,account:party.account,correspondent:party.correspondent};for(const [key,value] of Object.entries(map)){const el=form.elements.namedItem(k[key]);if(el)el.value=value||'';}
 const legacy=form.elements.namedItem(k.legacy);if(legacy)legacy.value='';if(role==='carrier'){const vehicle=form.elements.namedItem('vehicle');if(vehicle&&party.vehicle)vehicle.value=party.vehicle;}
 docQueueSave();docUpdatePreview();
}
function docPartySummary(d){return '<section class="party-requisites"><h2>Реквизиты сторон</h2>'+docPartyRoles(d.type).map(([role,label])=>{const k=docPartyKeys(role,d.type),fields=[['Наименование / ФИО',k.name],['Юридический адрес',k.address],['Почтовый адрес',k.postalAddress],['ИНН',k.inn],['КПП',k.kpp],['ОГРН / ОГРНИП',k.ogrn],['Телефон',k.phone],['Электронная почта',k.email],['Банк',k.bank],['БИК',k.bik],['Расчётный счёт',k.account],['Корреспондентский счёт',k.correspondent],['Подписант',k.sign],['Основание полномочий',k.basis]].filter(([,key])=>d[key]);return fields.length?'<h3>'+esc(label)+'</h3>'+docDetail(fields,d):'';}).join('')+'</section>';}

function localFieldsFor(type){
 if(DOC_NEW[type])return bizFields(type);
 let base=localDocumentFields.filter(([k])=>!['quantity','unit','price','amount','vat'].includes(k));
 if(!docTransport.includes(type))base=base.filter(([k])=>!['route','vehicle','driver','subject'].includes(k));
 if(type==='waybill')base=base.filter(([k])=>!['buyer','buyerDetails','buyerInn','subject'].includes(k));
 if(type==='reconcile')base=base.filter(([k])=>!['subject'].includes(k));
 if(['tn','order','contract'].includes(type))base.push(['amount','Стоимость перевозки, ₽'],['vat','Ставка НДС']);
 if(type==='tn')base=base.map(x=>x[0]==='buyer'?['buyer','Грузополучатель']:x[0]==='amount'?['amount','Стоимость перевозки без НДС, ₽']:x);
 const extras=(localExtraFields[type]||[]).concat(docExtra.common,docExtra[type]||[]);
 if(type==='upd')extras.push(...localExtraFields.vat);
 const seen=new Set();return base.concat(extras).filter(([k])=>!(type==='tn'&&k==='consignee')&&!seen.has(k)&&seen.add(k));
}
function docGroups(type){const all=localFieldsFor(type),partyKeys=new Set(docPartyRoles(type).flatMap(([r])=>Object.values(docPartyKeys(r,type))));['bank','bik','account','correspondent','customerSign','customerBasis'].forEach(k=>partyKeys.add(k));if(type==='order')partyKeys.add('shipper');
 const fields=all.filter(([k])=>!partyKeys.has(k));
 const groups=[['Участники',fields.filter(([k])=>['number','date','basis'].includes(k))],[DOC_NEW[type]?(type==='timesheet'?'Учёт времени':type==='advanceReport'?'Расходы':'Данные документа'):type==='reconcile'?'Операции':type==='waybill'?'Рейс и контроль':docItemTypes.includes(type)?'Товары и услуги':'Груз и перевозка',fields.filter(([k])=>!['number','date','basis','terms','contractTerms','extraTerms','liability','disputes','validUntil','acceptance','reconcileNote'].includes(k))],['Условия и подписи',fields.filter(([k])=>['terms','contractTerms','extraTerms','liability','disputes','validUntil','acceptance','reconcileNote'].includes(k))]];
 if(['tn','ttn'].includes(type)){groups[1][1].push(...groups[2][1]);return groups.slice(0,2);}return groups;
}
function docInput([key,label,kind],value){const attrs=' name="'+key+'" data-doc-field="'+key+'"';let field;if(kind?.startsWith('select|'))field='<select'+attrs+'><option value="">Выберите</option>'+kind.slice(7).split('|').map(x=>'<option '+(String(value??'')===x?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select>';else if(kind==='textarea')field='<textarea'+attrs+' rows="3">'+esc(value??'')+'</textarea>';else field='<input'+attrs+' type="'+(['date','datetime-local','month','time'].includes(kind)?kind:'text')+'" value="'+esc(value??'')+'">';return '<label>'+esc(label)+field+'</label>';}
function docItems(d){return Array.isArray(d.items)?d.items:[{subject:d.subject||'',quantity:d.quantity||'1',unit:d.unit||'шт.',price:d.price||d.amount||'',vat:d.vat||'Без НДС'}];}
function docItemsEditor(d){if(DOC_NEW[d.type])return bizItemsEditor(d);const headers=['Наименование','Кол-во','Ед.','Цена без НДС, ₽','НДС',''];return '<div class="doc-items"><h3>Товары и услуги</h3><p class="doc-hint">Цена за единицу указывается без НДС. Суммы рассчитываются автоматически.</p><div class="scroll"><table><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody id="doc-items-body">'+docItems(d).map((row,i)=>docItemRow(row,i)).join('')+'</tbody></table></div><button type="button" class="btn secondary" data-doc-add-item>＋ Добавить строку</button><p id="doc-totals" class="doc-totals"></p><details class="doc-item-details"><summary>Дополнительные реквизиты строки товара</summary><p class="doc-hint">Коды, упаковка, масса и реквизиты прослеживаемости заполняются при необходимости.</p><div id="doc-item-extras">'+docItems(d).map((row,i)=>docItemExtras(row,i)).join('')+'</div></details></div>';}
const docItemExtraFields=[['serialNumber','Серийный / инвентарный номер'],['condition','Состояние / комплектность'],['nomenclature','Номенклатурный номер'],['article','Артикул'],['package','Вид упаковки'],['perPlace','Количество в одном месте'],['places','Количество мест'],['grossMass','Масса брутто'],['stockNumber','Номер по складской картотеке'],['productCode','Код вида товара'],['unitCode','Код ОКЕИ'],['excise','Сумма акциза (или «без акциза»)'],['countryCode','Код страны'],['country','Страна'],['declaration','Рег. № декларации / партии'],['traceUnitCode','Код единицы прослеживаемости'],['traceUnit','Ед. прослеживаемости'],['traceQty','Количество прослеживаемого товара'],['traceValue','Стоимость прослеживаемого товара без НДС, ₽']];
function docItemRow(row,i){return '<tr data-item-index="'+i+'">'+['subject','quantity','unit','price'].map(k=>'<td><input aria-label="'+({subject:'Наименование',quantity:'Количество',unit:'Единица измерения',price:'Цена без НДС'}[k])+'" data-item-field="'+k+'" value="'+esc(row[k]??'')+'" '+(['quantity','price'].includes(k)?'inputmode="decimal"':'')+'></td>').join('')+'<td><select aria-label="Ставка НДС" data-item-field="vat">'+['Без НДС','0%','5%','7%','10%','20%','22%'].map(v=>'<option '+(v===(row.vat||'Без НДС')?'selected':'')+'>'+v+'</option>').join('')+'</select></td><td><button type="button" class="doc-remove" data-doc-remove-item="'+i+'" aria-label="Удалить строку '+(i+1)+'">×</button></td></tr>';}
