function docLedger(d){const rows=Array.isArray(d.operations)?d.operations:[{date:'',document:'',debit:'',credit:'',otherDebit:'',otherCredit:''}];return '<div class="doc-items"><h3>Операции за период</h3><p class="doc-hint">Дебет — начислено покупателю; кредит — получено от покупателя. В правой паре колонок вводятся соответствующие суммы по данным контрагента.</p><div class="scroll"><table><thead><tr>'+['Дата','Документ','Начислено, ₽','Оплачено, ₽','У контрагента: начислено','У контрагента: оплачено',''].map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody id="doc-ledger-body">'+rows.map((r,i)=>docLedgerRow(r,i)).join('')+'</tbody></table></div><button type="button" class="btn secondary" data-doc-add-operation>＋ Добавить операцию</button></div>';}
function docLedgerRow(r,i){return '<tr data-operation-index="'+i+'">'+['date','document','debit','credit','otherDebit','otherCredit'].map(k=>'<td><input type="'+(k==='date'?'date':'text')+'" aria-label="'+esc(k==='document'?'Документ операции':k==='date'?'Дата операции':({debit:'Начислено',credit:'Оплачено',otherDebit:'Начислено у контрагента',otherCredit:'Оплачено у контрагента'}[k]))+'" data-operation-field="'+k+'" value="'+esc(r[k]??'')+'" '+(!['date','document'].includes(k)?'inputmode="decimal"':'')+'></td>').join('')+'<td><button type="button" class="doc-remove" data-doc-remove-operation="'+i+'" aria-label="Удалить операцию">×</button></td></tr>';}
function docFormText(type){return ({ttn:'Форма № 1-Т',torg12:'Форма № ТОРГ-12',cashIn:'Форма № КО-1',cashOut:'Форма № КО-2',advanceReport:'Форма № АО-1',timesheet:'Форма № Т-13'})[type]||'';}
function docNotice(type){if(type==='selfContract'||type==='selfAct')return 'До оплаты проверьте статус НПД и применимость режима. Доходы от нынешнего работодателя и бывшего менее двух лет назад не подпадают под НПД. Чек «Мой налог» формирует исполнитель; акт его не заменяет.';if(type==='saleContract')return 'Шаблон предназначен для продажи движимого имущества. Перед подписанием проверьте предмет, цену и условия передачи.';if(type==='timesheet')return 'Указывайте фактическое время и коды явок / отсутствий. Итоги рассчитываются по введённым отметкам.';if(['tn','order'].includes(type))return 'С 01.09.2026 перевозочные документы оформляются электронно, кроме установленных исключений. Эта печатная форма не отправляется в ГИС ЭПД. Отсутствие интернета само по себе не подтверждает право на бумажное оформление.';if(['vat','upd'].includes(type))return 'Печатный проект с реквизитами 2026 года. Для формализованного ЭДО требуется XML и электронная подпись; PDF их не заменяет.';if(type==='waybill')return 'Форма с реквизитами по приказу Минтранса № 390. Отметки контроля и медосмотров заполняют и подписывают уполномоченные лица.';return 'Перед подписанием проверьте реквизиты, суммы и согласованные условия.';}
