 return '<div class="doc-workspace"><header class="doc-workspace-head"><div><span class="doc-eyebrow">БИЗНЕС AI · ДОКУМЕНТЫ</span><h2 id="doc-editor-title">'+esc(docLabel(localDocumentType))+'</h2><p>Заполните данные и подготовьте документ к печати</p>'+(docFormText(localDocumentType)?'<p class="doc-form-reference">'+esc(docFormText(localDocumentType))+'</p>':'')+'</div><button type="button" class="doc-close" data-local-doc-close aria-label="Закрыть редактор">×</button></header><div class="doc-split"><section class="doc-form-panel"><p id="doc-save-status" class="doc-save-status" role="status">'+(localDocumentRead().some(x=>x.id===localDocumentId)?'Черновик сохранён на устройстве':'Новый документ · заполните данные')+'</p><form id="local-document-form"><div class="doc-tabs" style="grid-template-columns:repeat('+groups.length+',minmax(0,1fr))" role="tablist" aria-label="Шаги заполнения">'+groups.map(([label],i)=>'<button type="button" id="doc-tab-'+i+'" role="tab" aria-controls="doc-step-'+i+'" aria-selected="'+(docStep===i)+'" data-doc-step="'+i+'" class="'+(docStep===i?'active':'')+'">'+(i+1)+'. '+esc(label)+'</button>').join('')+'</div>'+groups.map(([label,fields],i)=>'<section id="doc-step-'+i+'" role="tabpanel" aria-labelledby="doc-tab-'+i+'" '+(docStep!==i?'hidden':'')+'>'+''+'<div class="fields">'+fields.map(f=>docInput(f,d[f[0]])).join('')+'</div>'+(i===0?docPartyRoles(localDocumentType).map(([r,l])=>docPartyBlock(r,l,d)).join(''):'')+(i===1&&docItemTypes.includes(localDocumentType)?docItemsEditor(d):'')+(i===1&&localDocumentType==='reconcile'?docLedger(d):'')+(i===1&&localDocumentType==='advanceReport'?bizExpenseEditor(d):'')+(i===1&&localDocumentType==='timesheet'?bizTimeEditor(d):'')+'</section>').join('')+'<div class="doc-step-nav"><button type="button" class="btn secondary" data-doc-prev '+(docStep===0?'disabled':'')+'>← Назад</button><button type="button" class="btn secondary" data-doc-next '+(docStep===groups.length-1?'disabled':'')+'>Далее →</button></div><div class="actions"><button class="btn doc-primary" type="submit">Сохранить черновик</button><button class="btn secondary" type="button" data-doc-example>Заполнить пример</button><button class="btn secondary" type="button" data-doc-json>Копия черновика</button></div><p class="doc-hint">Данные сохраняются автоматически в этом браузере. Для переноса на другое устройство скачайте копию черновика.</p></form><p class="doc-notice">'+esc(docNotice(localDocumentType))+'</p></section><section class="doc-result-panel"><div class="doc-result-head"><h3>Результат заполнения</h3><div class="actions"><button class="btn doc-primary" type="button" data-doc-pdf>Скачать PDF</button><button class="btn secondary" type="button" data-local-doc-print>Печать</button><button class="btn secondary" type="button" data-local-doc-download>Скачать HTML</button></div></div><p class="doc-hint">Предпросмотр обновляется при вводе. Выберите поле — соответствующая строка бланка подсветится.</p><p id="doc-field-hint" class="doc-hint" role="status">Выберите поле слева — нужная строка бланка подсветится</p><iframe id="doc-preview" title="Предпросмотр готового документа" sandbox="allow-same-origin"></iframe></section></div></div>';
