function docSearchNormalize(value){return String(value??'').toLocaleLowerCase('ru-RU').replace(/ё/g,'е').normalize('NFKC').replace(/[^\p{L}\p{N}]+/gu,' ').trim();}
function docSearchText(type,record){return docSearchNormalize([docLabel(type),docMeta[type]?.join(' '),docSearchAliases[type],record?.number,record?.date,record?.seller,record?.buyer,record?.carrier,record?.subject,record?.route,...(Array.isArray(record?.items)?record.items:[]).map(x=>x.subject)].filter(Boolean).join(' '));}
function docSearchMatches(text,query=docSearchQuery){const tokens=docSearchNormalize(query).split(/\s+/).filter(Boolean),words=String(text).split(/\s+/);return tokens.every(token=>words.some(word=>token.length<=2?word===token:word.startsWith(token)));}
function docSearchCounts(){const drafts=localDocumentRead(),templates=localDocumentTypes.filter(([type])=>docSearchMatches(docSearchText(type))).length,saved=drafts.filter(d=>docSearchMatches(docSearchText(d.type,d))).length;return {templates,saved,totalDrafts:drafts.length};}
function docSearchToolbar(){const n=docSearchCounts();return '<div class="doc-search"><label for="document-search">Поиск бланков и черновиков</label><div class="doc-search-row"><input type="search" id="document-search" value="'+esc(docSearchQuery)+'" placeholder="Название, сокращение, номер или контрагент" autocomplete="off" aria-controls="doc-template-cards doc-saved-records"><button type="button" class="btn secondary" data-doc-search-clear '+(!docSearchQuery?'hidden':'')+'>Очистить</button></div><p class="doc-hint" id="doc-search-status" role="status" aria-live="polite">Бланки: '+n.templates+' из '+localDocumentTypes.length+' · Черновики: '+n.saved+' из '+n.totalDrafts+'</p></div>';}
function docApplySearch(){const pageEl=document.querySelector('.doc-page');if(!pageEl)return;let templates=0,saved=0,totalDrafts=0;pageEl.querySelectorAll('[data-doc-search-entry]').forEach(el=>{const match=docSearchMatches(el.dataset.docSearchText);el.hidden=!match;if(el.dataset.docSearchEntry==='template'){if(match)templates++;}else{totalDrafts++;if(match)saved++;}});const status=document.getElementById('doc-search-status');if(status)status.textContent='Бланки: '+templates+' из '+localDocumentTypes.length+' · Черновики: '+saved+' из '+totalDrafts;const empty=pageEl.querySelector('[data-doc-search-empty]');if(empty)empty.hidden=templates>0;const draftEmpty=pageEl.querySelector('[data-doc-draft-search-empty]');if(draftEmpty)draftEmpty.hidden=!(docSearchQuery&&totalDrafts>0&&saved===0);const clear=pageEl.querySelector('[data-doc-search-clear]');if(clear)clear.hidden=!docSearchQuery;}
document.addEventListener('input',e=>{if(e.target.id==='document-search'){docSearchQuery=e.target.value;docApplySearch();}});
document.addEventListener('click',e=>{if(!e.target.closest('[data-doc-search-clear]'))return;docSearchQuery='';const input=document.getElementById('document-search');if(input){input.value='';input.focus();}docApplySearch();});

function documentsPage(){return '<section class="doc-page"><div class="doc-page-head"><div><span class="doc-eyebrow">БИЗНЕС AI</span><h2 class="home-title">Документы</h2><p class="muted">Заполнение, предпросмотр и печать. Черновики остаются на вашем устройстве.</p></div><a class="btn secondary" href="documents-offline.html" download>↓ Редактор без интернета</a></div>'+docSearchToolbar()+'<div id="doc-template-cards" class="local-doc-types">'+localDocumentTypes.map(([type,label])=>'<button type="button" class="local-doc-type" data-doc-search-entry="template" data-doc-search-text="'+esc(docSearchText(type))+'" '+(docSearchMatches(docSearchText(type))?'':'hidden')+' data-local-doc-new="'+type+'"><span class="doc-type-icon">▤</span><span><small>'+docMeta[type][0]+'</small><strong>'+esc(label)+'</strong><small>'+docMeta[type][1]+'</small></span><span class="doc-type-arrow">›</span></button>').join('')+'</div><p class="doc-search-empty" data-doc-search-empty '+(docSearchCounts().templates?'hidden':'')+'>Бланки не найдены. Попробуйте другое название или сокращение.</p><div class="actions"><button class="btn secondary directory-toggle-btn" type="button" data-dir-toggle>Справочник реквизитов</button><label class="btn secondary">Импорт черновика<input type="file" accept="application/json,.json" data-doc-import hidden></label></div>'+(localDirectoryOpen?localDirectoryEditor():'')+'<div class="card section"><h3>Мои черновики на этом устройстве</h3><div class="local-doc-list" id="doc-saved-records">'+(localDocumentRead().map(d=>'<div class="local-doc-record" data-doc-search-entry="draft" data-doc-search-text="'+esc(docSearchText(d.type,d))+'" '+(docSearchMatches(docSearchText(d.type,d))?'':'hidden')+'><span><strong>'+esc(docLabel(d.type))+'</strong> № '+esc(d.number||'без номера')+' · '+esc(d.date||'без даты')+'</span><div class="actions"><button type="button" class="btn secondary" data-local-doc-open="'+esc(d.id)+'">Открыть</button><button type="button" class="btn secondary" data-local-doc-delete="'+esc(d.id)+'">Удалить</button></div></div>').join('')||'<p class="muted">Пока нет сохранённых черновиков.</p>')+'</div><p class="doc-hint" data-doc-draft-search-empty '+(docSearchQuery&&docSearchCounts().totalDrafts&&docSearchCounts().saved===0?'':'hidden')+'>Черновики по этому запросу не найдены.</p></div>'+(localDocumentId!==null?'<div class="local-doc-modal doc-modal" data-local-doc-backdrop><div class="local-doc-modal-panel doc-modal-panel" role="dialog" aria-modal="true" aria-labelledby="doc-editor-title">'+localDocumentEditor()+'</div></div>':'')+'</section>';}
function localDocumentData(){const f=document.getElementById('local-document-form');if(!f)return null;const data=Object.fromEntries(new FormData(f).entries());const old=docPending||localDocumentRead().find(x=>x.id===localDocumentId)||{};const rows=[...f.querySelectorAll('[data-item-index]')].map((tr,i)=>{const x=Object.fromEntries([...tr.querySelectorAll('[data-item-field]')].map(el=>[el.dataset.itemField,el.value]));f.querySelectorAll('[data-item-extra-index="'+i+'"] [data-item-extra]').forEach(el=>x[el.dataset.itemExtra]=el.value);return x;});const operations=[...f.querySelectorAll('[data-operation-index]')].map(tr=>Object.fromEntries([...tr.querySelectorAll('[data-operation-field]')].map(el=>[el.dataset.operationField,el.value])));return docNormalizeParties({...old,...data,...bizReadRows(f,localDocumentType,old),id:localDocumentId||uid(),type:localDocumentType,...(docItemTypes.includes(localDocumentType)?{items:rows}:{}),...(localDocumentType==='reconcile'?{operations}:{}),updatedAt:new Date().toISOString()});}
function docNum(x){const n=Number(String(x??'').replace(/\s/g,'').replace(',','.'));return Number.isFinite(n)?n:0;}
function docCash(n){return (Math.round(n*100)/100).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2});}
function docMoney(n){return docCash(n)+' ₽';}
function docCalculate(d){return docItems(d).map((r,i)=>{const net=Math.round(docNum(r.quantity)*docNum(r.price)*100),rate=r.vat==='Без НДС'?0:docNum(String(r.vat).replace('%','')),tax=Math.round(net*rate/100);const source=d.tripGrossItem;if(i===0&&source&&Number.isInteger(source.tripGrossCents)&&['quantity','price','vat'].every(k=>String(r[k])===String(source[k]))&&String(r.quantity)==='1'&&net===Math.round(source.tripGrossCents/(1+rate/100)))return {...r,net:net/100,tax:(source.tripGrossCents-net)/100,total:source.tripGrossCents/100};return {...r,net:net/100,tax:tax/100,total:(net+tax)/100};});}
function docTotal(rows,key){return rows.reduce((n,r)=>n+Math.round(r[key]*100),0)/100;}
function docDetail(fields,d){return '<table class="details"><tbody>'+fields.map(([name,key])=>'<tr><th>'+esc(name)+'</th><td>'+esc(d[key]||'—')+'</td></tr>').join('')+'</tbody></table>';}
function docTable(headers,rows){return '<table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(c=>'<td>'+esc(c??'—')+'</td>').join('')+'</tr>').join('')+'</tbody></table>';}
function localDocumentHTML(d){return docSceneHTML(docBuildScene(d));}
function docUpdatePreview(){const d=localDocumentData(),frame=document.getElementById('doc-preview');if(!d||!frame)return;const previous=frame.contentWindow?.scrollY||0;frame.onload=()=>{if(docActiveField)docHighlightField(docActiveField,true);else frame.contentWindow.scrollTo(0,previous);frame.contentDocument?.addEventListener('click',e=>{const target=e.target.closest('[data-fields]');if(target)docFocusBlankField(target.dataset.fields.split('|').filter(Boolean));});};frame.srcdoc=localDocumentHTML(d);const totalEl=document.getElementById('doc-totals');if(totalEl){const rows=docCalculate(d);totalEl.textContent='Без НДС: '+docMoney(docTotal(rows,'net'))+' · НДС: '+docMoney(docTotal(rows,'tax'))+' · Итого: '+docMoney(docTotal(rows,'total'));}}
function docMount(){const frame=document.getElementById('doc-preview');if(!frame||frame.dataset.mounted)return;frame.dataset.mounted='true';docUpdatePreview();if(!window.docPdfFont)docLoadPDF().then(()=>{if(document.getElementById('doc-preview')===frame)docUpdatePreview();}).catch(()=>{});document.querySelector('[data-doc-field="number"]')?.focus();}
function docQueueSave(){docDirty=true;docStatus('Сохраняем…');clearTimeout(docSaveTimer);clearTimeout(docPreviewTimer);docPreviewTimer=setTimeout(docUpdatePreview,180);docSaveTimer=setTimeout(docFlush,450);}
function docFlush(){clearTimeout(docSaveTimer);if(!docDirty)return true;try{const d=localDocumentData();if(d)localDocumentSave(d);return true;}catch(e){docStatus('Не удалось сохранить. Скачайте копию черновика.',true);return false;}}
function docOpen(type,id=null){if(!docFlush())return;docReturnFocus=document.activeElement;localDocumentType=type;localDocumentId=id||uid();docStep=0;docPending=null;docActiveField='';const record=localDocumentRead().find(x=>x.id===id);if(record){docPending={...record};if(record.type==='tn'&&!record.buyer)docPending.buyer=record.consignee||'';}if(!record)docPending={id:localDocumentId,type,date:docDate(),currency:'Российский рубль, 643',status:'1'};else if(docItemTypes.includes(type)&&!record.items){docPending={...record,items:docItems(record).map(r=>({...r,...Object.fromEntries(docItemExtraFields.filter(([k])=>record[k]).map(([k])=>[k,record[k]]))}))};}render();if(!record){const db=localDirectoryRead();if(db.defaultId)docFillParty('seller',db.defaultId);}docMount();}
async function docClose(){if(!await appSaveBeforeLeave(true))return;clearTimeout(docPreviewTimer);localDocumentId=null;docPending=null;render();docReturnFocus?.isConnected&&docReturnFocus.focus();}
function docSwitchStep(step){docStep=Math.max(0,Math.min(docGroups(localDocumentType).length-1,step));document.querySelectorAll('[data-doc-step]').forEach((b,i)=>{b.classList.toggle('active',i===docStep);b.setAttribute('aria-selected',String(i===docStep));});document.querySelectorAll('[role="tabpanel"][id^="doc-step-"]').forEach((el,i)=>el.hidden=i!==docStep);const prev=document.querySelector('[data-doc-prev]'),next=document.querySelector('[data-doc-next]');if(prev)prev.disabled=docStep===0;if(next)next.disabled=docStep===docGroups(localDocumentType).length-1;document.querySelector('[data-doc-step="'+docStep+'"]')?.focus();}
function docDownload(text,name,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
