function blankAdditional(s,d){const all=localFieldsFor(d.type);for(const [role,label] of docPartyRoles(d.type)){const k=docPartyKeys(role,d.type);for(const [field,key] of Object.entries(k)){if(field==='name')continue;all.push([key,label+': '+({inn:'ИНН',kpp:'КПП',ogrn:'ОГРН / ОГРНИП',address:'Адрес',postalAddress:'Почтовый адрес',phone:'Телефон',email:'Электронная почта',sign:'Подписант',basis:'Основание полномочий',bank:'Банк',bik:'БИК',account:'Расчётный счёт',correspondent:'Корреспондентский счёт',legacy:'Ранее сохранённые реквизиты'}[field]||field)]);}}
 const seen=new Set();const extra=all.filter(([key])=>!seen.has(key)&&seen.add(key)&&!s.used.has(key)&&String(d[key]??'').trim());if(extra.length){s.title('Дополнительные сведения');for(const [key,label] of extra)s.ruled(label,d[key],[key],9);}}
function docBuildSceneAt(input,profile=0){const d=docNormalizeParties(input),s=blankScene(d.type,profile);if(DOC_NEW[d.type])bizBuild(s,d);else switch(d.type){case 'tn':blankTransport(s,d);break;case 'ttn':blankCommodity(s,d,true);break;case 'torg12':blankCommodity(s,d,false);break;case 'invoice':blankInvoice(s,d);break;case 'act':blankAct(s,d);break;case 'vat':blankTax(s,d,false);break;case 'upd':blankTax(s,d,true);break;case 'waybill':blankWaybill(s,d);break;case 'reconcile':blankReconcile(s,d);break;case 'order':blankContract(s,d,true);break;default:blankContract(s,d,false);}
 blankAdditional(s,d);s.pages.forEach((page,i)=>{page.ops.push({kind:'line',x:9,y:s.h-11,x2:s.w-9,y2:s.h-11});page.ops.push({kind:'text',text:DOC_BLANK_BRAND,x:9,y:s.h-6,size:6.3,align:'left'},{kind:'text',text:(i+1)+' / '+s.pages.length,x:s.w-9,y:s.h-6,size:6.3,align:'right'});});return s;}
function docBuildScene(input){let best=docBuildSceneAt(input,0);const minimum=1+best.forcedBreaks;if(best.pages.length===minimum)return best;for(let profile=1;profile<DOC_PAGE_PROFILES.length;profile++){const candidate=docBuildSceneAt(input,profile);if(candidate.pages.length<best.pages.length)best=candidate;if(best.pages.length===minimum)break;}return best;}
function docSceneHTML(scene){const escAttr=esc,font=window.docPdfFont?'@font-face{font-family:BlankFont;src:url(data:font/ttf;base64,'+window.docPdfFont+')}':'';const pages=scene.pages.map((page,i)=>'<section class="blank-page" data-blank-page="'+i+'" style="aspect-ratio:'+scene.w+'/'+scene.h+'"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '+scene.w+' '+scene.h+'" role="img" aria-label="Страница '+(i+1)+' документа">'+page.ops.map(op=>op.kind==='text'?'<text x="'+op.x+'" y="'+op.y+'" font-size="'+(op.size*25.4/72)+'" '+(op.bold?'font-weight="bold" ':'')+'text-anchor="'+({left:'start',center:'middle',right:'end'}[op.align]||'start')+'">'+esc(op.text)+'</text>':op.kind==='line'?'<line x1="'+op.x+'" y1="'+op.y+'" x2="'+op.x2+'" y2="'+op.y2+'"/>':'<rect x="'+op.x+'" y="'+op.y+'" width="'+op.w+'" height="'+op.h+'"/>').join('')+page.marks.map(mark=>'<rect class="field-target" data-fields="'+escAttr('|'+mark.keys.join('|')+'|')+'" x="'+mark.x+'" y="'+mark.y+'" width="'+mark.w+'" height="'+mark.h+'"/>').join('')+'</svg></section>').join('');return '<!doctype html><html lang="ru"><head><meta charset="UTF-8"><title>'+esc(docLabel(scene.type))+'</title><style>'+font+'*{box-sizing:border-box}html{scroll-behavior:auto}body{margin:0;background:#e5e9ed;padding:12px}.blank-page{width:100%;max-width:'+scene.w+'mm;background:white;margin:0 auto 15px;box-shadow:0 2px 12px #0002;break-after:page;page-break-after:always}.blank-page:last-child{break-after:auto;page-break-after:auto}svg{display:block;width:100%;height:100%;font-family:BlankFont,"DejaVu Sans",Arial,sans-serif}svg text{fill:#111;stroke:none}svg line,svg rect{fill:none;stroke:#111;stroke-width:.2}.field-target{fill:transparent;stroke:none;cursor:pointer}.field-target.active{fill:#00a99b;fill-opacity:.16;stroke:#008f83;stroke-width:.5}svg text{pointer-events:none}@page{size:A4 '+(scene.w>scene.h?'landscape':'portrait')+';margin:0}@media print{body{padding:0;background:white}.blank-page{width:'+scene.w+'mm;height:'+scene.h+'mm;max-width:none;margin:0;box-shadow:none}.field-target{display:none!important}}</style></head><body>'+pages+'</body></html>';}

let docActiveField='',docFocusScroll=true;
function docInputKey(el){if(!el)return '';if(el.dataset.docGridKey)return el.dataset.docGridKey;if(el.dataset.docField)return el.dataset.docField;if(el.dataset.itemField)return 'item:'+el.closest('[data-item-index]').dataset.itemIndex+':'+el.dataset.itemField;if(el.dataset.itemExtra)return 'item:'+el.closest('[data-item-extra-index]').dataset.itemExtraIndex+':'+el.dataset.itemExtra;if(el.dataset.operationField)return 'operation:'+el.closest('[data-operation-index]').dataset.operationIndex+':'+el.dataset.operationField;return '';}
function docHighlightField(key,scroll=true){const frame=document.getElementById('doc-preview'),inner=frame?.contentDocument;if(!inner)return;const targets=[...inner.querySelectorAll('[data-fields]')];targets.forEach(el=>el.classList.toggle('active',!!key&&el.dataset.fields.includes('|'+key+'|')));const first=targets.find(el=>el.classList.contains('active'));if(first&&scroll){const bounds=first.getBoundingClientRect();frame.contentWindow.scrollTo({top:Math.max(0,frame.contentWindow.scrollY+bounds.top-frame.clientHeight*.3),behavior:'auto'});}const hint=document.getElementById('doc-field-hint');if(hint)hint.textContent=key?(first?'Подсвечена строка документа для выбранного поля':'Поле отобразится в дополнительных сведениях после заполнения'):'Выберите поле слева — нужная строка бланка подсветится';}
function docFocusBlankField(keys){const form=document.getElementById('local-document-form');if(!form)return;for(const key of keys){const grid=form.querySelector('[data-doc-grid-key="'+key+'"]');if(grid){const panel=grid.closest('[role="tabpanel"]');if(panel)docSwitchStep(Number(panel.id.replace('doc-step-','')));grid.focus();grid.scrollIntoView({block:'center'});return;}}for(const key of keys){let el;if(key.startsWith('item:')){const [,i,k]=key.split(':');el=form.querySelector('[data-item-index="'+i+'"] [data-item-field="'+k+'"]')||form.querySelector('[data-item-extra-index="'+i+'"] [data-item-extra="'+k+'"]');}else if(key.startsWith('operation:')){const [,i,k]=key.split(':');el=form.querySelector('[data-operation-index="'+i+'"] [data-operation-field="'+k+'"]');}else el=form.elements.namedItem(key);if(el&&el.focus){const panel=el.closest('[role="tabpanel"]');if(panel)docSwitchStep(Number(panel.id.replace('doc-step-','')));for(const details of [...el.closest('form').querySelectorAll('details')])if(details.contains(el))details.open=true;el.focus();el.scrollIntoView({block:'center',behavior:'smooth'});return;}}}
document.addEventListener('focusin',e=>{if(!e.target.closest('#local-document-form'))return;const key=docInputKey(e.target);if(key){docActiveField=key;docHighlightField(key,true);}});

function bizFields(type){const def=DOC_NEW[type],base=[['number','Номер документа'],['date','Дата составления','date'],['basis','Основание / связанный документ']];return base.concat(def.fields,[['terms','Дополнительные условия / сведения','textarea']]);}
function bizPartyIdentity(role,d){const type=localDocumentType;return '<details class="doc-party-bank"><summary>Статус стороны и документ, удостоверяющий личность</summary><div class="fields">'+docInput([role+'PersonType','Статус стороны','select|Организация|ИП|Физическое лицо|Самозанятый'],d[role+'PersonType'])+docInput([role+'Identity','Документ: вид, серия и номер'],d[role+'Identity'])+docInput([role+'IssuedBy','Кем выдан документ'],d[role+'IssuedBy'])+docInput([role+'IssuedOn','Дата выдачи','date'],d[role+'IssuedOn'])+docInput([role+'BirthDate','Дата рождения','date'],d[role+'BirthDate'])+docInput([role+'BirthPlace','Место рождения'],d[role+'BirthPlace'])+'</div></details>';}
function bizItemsEditor(d){const def=DOC_NEW[d.type],priced=!def.property;return '<div class="doc-items"><h3>'+({power:'Перечень получаемых ценностей',estimate:'Работы и материалы',selfAct:'Услуги / результаты работ'}[def.kind]||(def.property?'Перечень имущества':'Товары / услуги / спецификация'))+'</h3><p class="doc-hint">'+(priced?'Цена за единицу указывается без НДС. Итоги рассчитываются автоматически.':'Укажите наименование, единицу измерения и количество. Состояние и серийный номер — в дополнительных реквизитах строки.')+'</p><div class="scroll"><table><thead><tr><th>Наименование</th><th>Количество</th><th>Ед.</th>'+(priced?'<th>Цена без НДС, ₽</th><th>НДС</th>':'')+'<th></th></tr></thead><tbody id="doc-items-body">'+docItems(d).map((r,i)=>'<tr data-item-index="'+i+'">'+['subject','quantity','unit',...(priced?['price']:[])].map(k=>'<td><input data-item-field="'+k+'" aria-label="'+({subject:'Наименование',quantity:'Количество',unit:'Единица измерения',price:'Цена'}[k])+'" value="'+esc(r[k]??'')+'" '+(['quantity','price'].includes(k)?'inputmode="decimal"':'')+'></td>').join('')+(priced?'<td><select data-item-field="vat" aria-label="НДС">'+(def.noVat?['Без НДС']:['Без НДС','0%','5%','7%','10%','22%']).map(v=>'<option '+((r.vat||'Без НДС')===v?'selected':'')+'>'+v+'</option>').join('')+'</select></td>':'')+'<td><button type="button" class="doc-remove" data-doc-remove-item="'+i+'" aria-label="Удалить строку">×</button></td></tr>').join('')+'</tbody></table></div><button type="button" class="btn secondary" data-doc-add-item>＋ Добавить строку</button>'+(priced?'<p id="doc-totals" class="doc-totals"></p>':'')+'<details class="doc-item-details"><summary>Дополнительные реквизиты строк</summary><div id="doc-item-extras">'+docItems(d).map((r,i)=>docItemExtras(r,i)).join('')+'</div></details></div>';}
function bizExpenseEditor(d){const rows=Array.isArray(d.expenses)?d.expenses:[{}];return '<div class="doc-items"><h3>Подтверждённые расходы</h3><div class="scroll"><table><thead><tr>'+['Дата','Документ №','Кем выдан','Содержание расхода','Сумма, ₽','Счёт',''].map(t=>'<th>'+t+'</th>').join('')+'</tr></thead><tbody>'+rows.map((r,i)=>'<tr data-expense-index="'+i+'">'+['date','document','issuer','description','amount','account'].map(k=>'<td><input type="'+(k==='date'?'date':'text')+'" aria-label="'+esc('Расход '+(i+1)+' '+k)+'" data-expense-field="'+k+'" data-doc-grid-key="expense:'+i+':'+k+'" value="'+esc(r[k]??'')+'" '+(k==='amount'?'inputmode="decimal"':'')+'></td>').join('')+'<td><button type="button" class="doc-remove" data-biz-expense-remove="'+i+'" aria-label="Удалить расход">×</button></td></tr>').join('')+'</tbody></table></div><button type="button" class="btn secondary" data-biz-expense-add>＋ Добавить расход</button><p class="doc-hint">Фиксируются фактические расходы с реквизитами подтверждающих документов.</p></div>';}
function bizMonth(d){const m=/^(\d{4})-(\d{2})$/.exec(d.reportMonth||docDate().slice(0,7));const year=m?Number(m[1]):new Date().getFullYear(),month=m?Number(m[2]):new Date().getMonth()+1;return {year,month,days:new Date(year,month,0).getDate()};}
function bizTimeEditor(d){const rows=Array.isArray(d.timeEntries)?d.timeEntries:[{name:'',personnel:'',days:[]}],month=bizMonth(d);return '<div class="doc-items"><h3>Работники и ежедневные отметки</h3><p class="doc-hint">В каждой дате: код явки / отсутствия и фактические часы (0–24). Праздники и график автоматически не подставляются. Например: Я — явка, В — выходной, ОТ — отпуск, Б — больничный.</p><div class="scroll"><table class="doc-timesheet-editor"><thead><tr><th>ФИО / табельный номер</th>'+Array.from({length:month.days},(_,i)=>'<th>'+(i+1)+'</th>').join('')+'<th></th></tr></thead><tbody>'+rows.map((r,i)=>'<tr data-time-index="'+i+'"><td><input aria-label="ФИО работника" data-time-field="name" data-doc-grid-key="time:'+i+':name" value="'+esc(r.name||'')+'"><input aria-label="Табельный номер работника" data-time-field="personnel" data-doc-grid-key="time:'+i+':personnel" value="'+esc(r.personnel||'')+'"></td>'+Array.from({length:month.days},(_,day)=>{const x=r.days?.[day]||{};return '<td data-time-day="'+day+'"><input aria-label="Код за '+(day+1)+' число" data-time-cell="code" data-doc-grid-key="time:'+i+':'+day+':code" value="'+esc(x.code||'')+'"><input aria-label="Часы за '+(day+1)+' число" data-time-cell="hours" data-doc-grid-key="time:'+i+':'+day+':hours" inputmode="decimal" value="'+esc(x.hours||'')+'"></td>';}).join('')+'<td><button type="button" class="doc-remove" data-biz-time-remove="'+i+'" aria-label="Удалить работника">×</button></td></tr>').join('')+'</tbody></table></div><button type="button" class="btn secondary" data-biz-time-add>＋ Добавить работника</button></div>';}
function bizReadRows(form,type,old){const out={};if(type==='advanceReport')out.expenses=[...form.querySelectorAll('[data-expense-index]')].map(tr=>Object.fromEntries([...tr.querySelectorAll('[data-expense-field]')].map(el=>[el.dataset.expenseField,el.value])));if(type==='timesheet')out.timeEntries=[...form.querySelectorAll('[data-time-index]')].map((tr,i)=>({name:tr.querySelector('[data-time-field="name"]').value,personnel:tr.querySelector('[data-time-field="personnel"]').value,days:Array.from({length:31},(_,day)=>{const cell=tr.querySelector('[data-time-day="'+day+'"]');return cell?{code:cell.querySelector('[data-time-cell="code"]').value,hours:cell.querySelector('[data-time-cell="hours"]').value}:(old.timeEntries?.[i]?.days?.[day]||{code:'',hours:''});})}));return out;}
function bizValidImport(d){for(const key of ['items','operations','expenses'])if(d[key]&&(!Array.isArray(d[key])||d[key].length>500||d[key].some(r=>!r||typeof r!=='object'||Object.values(r).some(v=>typeof v!=='string'))))throw Error('Некорректные строки '+key);if(d.timeEntries&&(!Array.isArray(d.timeEntries)||d.timeEntries.length>200||d.timeEntries.some(r=>!r||typeof r.name!=='string'||typeof r.personnel!=='string'||!Array.isArray(r.days)||r.days.length>31||r.days.some(x=>!x||typeof x.code!=='string'||typeof x.hours!=='string'))))throw Error('Некорректные отметки табеля');}
function bizValidation(d){if(DOC_NEW[d.type]){for(const key of ['amount','salary','deposit','advanceReceived','debtAmount','penaltyAmount','interestAmount','remainingDebt'])if(d[key]&&!/^\d+(?:[.,]\d{1,2})?$/.test(String(d[key]).replace(/\s/g,'')))return 'Проверьте денежные суммы: используйте неотрицательное число с точностью до копеек.';if(d.type==='employment'&&d.contractDuration==='На неопределённый срок'&&d.endDate)return 'В бессрочном трудовом договоре не указывайте дату окончания. Для срочного договора выберите соответствующий вид и основание.';if(d.previousBalance&&!/^-?\d+(?:[.,]\d{1,2})?$/.test(String(d.previousBalance).replace(/\s/g,'')))return 'Проверьте остаток предыдущего аванса.';if(d.interestMode==='Процентный'&&(!String(d.interestRate||'').trim()||!/^\d+(?:[.,]\d+)?$/.test(d.interestRate)))return 'Для процентного займа укажите ставку, % годовых.';if(d.type==='loanReturnReceipt'&&d.returnScope==='Полный возврат'&&docNum(d.remainingDebt)!==0)return 'При полном возврате остаток основного долга должен быть равен нулю.';if(d.type==='timesheet'&&d.reportMonth&&!/^\d{4}-(?:0[1-9]|1[0-2])$/.test(d.reportMonth))return 'Укажите корректный отчётный месяц.';}if(d.vin&&(!/^[A-HJ-NPR-Z0-9]{17}$/i.test(d.vin.replace(/\s/g,''))))return 'VIN должен содержать 17 латинских букв и цифр без I, O, Q. Для ТС без VIN укажите сведения в описании.';if(d.type==='timesheet'&&(d.timeEntries||[]).some(r=>(r.days||[]).some(x=>x.hours&&(!/^\d+(?:[.,]\d+)?$/.test(x.hours)||docNum(x.hours)>24))))return 'Часы в табеле должны быть числом от 0 до 24.';if(d.type==='advanceReport'&&(d.expenses||[]).some(r=>r.amount&&!/^\d+(?:[.,]\d+)?$/.test(r.amount)))return 'Проверьте суммы расходов: укажите неотрицательные числа.';return '';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-biz-expense-add],[data-biz-expense-remove],[data-biz-time-add],[data-biz-time-remove]');if(!b)return;const d=localDocumentData();if(!d)return;if(b.hasAttribute('data-biz-expense-add'))(d.expenses||(d.expenses=[])).push({date:'',document:'',issuer:'',description:'',amount:'',account:''});if(b.hasAttribute('data-biz-expense-remove'))d.expenses.splice(Number(b.dataset.bizExpenseRemove),1);if(b.hasAttribute('data-biz-time-add'))(d.timeEntries||(d.timeEntries=[])).push({name:'',personnel:'',days:Array.from({length:31},()=>({code:'',hours:''}))});if(b.hasAttribute('data-biz-time-remove'))d.timeEntries.splice(Number(b.dataset.bizTimeRemove),1);docPending=d;docDirty=true;render();docMount();docFlush();});

function bizWordForm(n,forms){const x=Math.abs(n)%100;return forms[x>=11&&x<=14?2:x%10===1?0:x%10>=2&&x%10<=4?1:2];}
function bizIntegerWords(number){if(!number)return 'ноль';const units=['','один','два','три','четыре','пять','шесть','семь','восемь','девять'],fem=['','одна','две','три','четыре','пять','шесть','семь','восемь','девять'],teens=['десять','одиннадцать','двенадцать','тринадцать','четырнадцать','пятнадцать','шестнадцать','семнадцать','восемнадцать','девятнадцать'],tens=['','','двадцать','тридцать','сорок','пятьдесят','шестьдесят','семьдесят','восемьдесят','девяносто'],hundreds=['','сто','двести','триста','четыреста','пятьсот','шестьсот','семьсот','восемьсот','девятьсот'],groups=[null,['тысяча','тысячи','тысяч'],['миллион','миллиона','миллионов'],['миллиард','миллиарда','миллиардов']];let n=Math.floor(Math.abs(number)),parts=[],i=0;while(n&&i<4){const x=n%1000;if(x){let p=[];if(Math.floor(x/100))p.push(hundreds[Math.floor(x/100)]);const tail=x%100;if(tail>=10&&tail<20)p.push(teens[tail-10]);else{if(Math.floor(tail/10))p.push(tens[Math.floor(tail/10)]);if(tail%10)p.push((i===1?fem:units)[tail%10]);}if(i)p.push(bizWordForm(x,groups[i]));parts.unshift(p.join(' '));}n=Math.floor(n/1000);i++;}return (number<0?'минус ':'')+parts.join(' ');}
function bizMoneyWords(value){const cents=Math.round(docNum(value)*100),rub=Math.floor(Math.abs(cents)/100),kop=Math.abs(cents)%100;if(rub>=1e12)return docCash(docNum(value))+' руб.';const text=(cents<0?'минус ':'')+bizIntegerWords(rub)+' '+bizWordForm(rub,['рубль','рубля','рублей'])+' '+String(kop).padStart(2,'0')+' '+bizWordForm(kop,['копейка','копейки','копеек']);return text.charAt(0).toUpperCase()+text.slice(1);}
function bizValue(d,key){return blankGet(d,key)||'________________';}
function bizP(s,d,title,text,keys=[]){s.title(title);s.paragraph(text,keys);}
