function bizEmployment(s,d){bizStart(s,d,'ТРУДОВОЙ ДОГОВОР');bizPartyPreamble(s,d);bizP(s,d,'1. Трудовая функция и место работы','Работодатель предоставляет Работнику работу по согласованной трудовой функции, обеспечивает условия труда и выплачивает заработную плату. Работник лично выполняет трудовую функцию и соблюдает правила внутреннего трудового распорядка.');s.cells([blankCell(d,'position','Должность / профессия'),blankCell(d,'workplace','Место работы, подразделение')],13);s.ruled('Трудовая функция',d.jobFunction,['jobFunction'],17);s.title('2. Начало работы и срок договора');s.cells([blankCell(d,'startDate','Дата начала работы'),blankCell(d,'contractDuration','Срок договора'),blankCell(d,'employmentType','Основная работа / совместительство')],13);if(d.contractDuration==='Срочный')s.cells([blankCell(d,'endDate','Дата окончания'),blankCell(d,'fixedTermReason','Основание заключения срочного договора')],14);s.ruled('Условие об испытании (если согласовано)',d.probation,['probation'],12);s.title('3. Оплата труда');s.cells([blankCell(d,'salary','Оклад / тарифная ставка до удержаний, руб.'),blankCell(d,'payDates','Даты выплаты заработной платы')],13);s.ruled('Доплаты, надбавки и премии',d.bonusTerms,['bonusTerms'],15);bizP(s,d,'4. Рабочее время и отдых',bizValue(d,'workSchedule'),['workSchedule']);s.ruled('Ежегодный оплачиваемый отпуск',d.leaveTerms,['leaveTerms'],12);s.title('5. Условия труда и гарантии');s.ruled('Условия труда на рабочем месте / класс СОУТ',d.workConditions,['workConditions'],14);s.ruled('Характер работы',d.jobNature,['jobNature'],12);s.paragraph('Работник подлежит обязательному социальному страхованию в порядке, установленном законодательством Российской Федерации. Дополнительные гарантии и компенсации: '+bizValue(d,'guarantees')+'.',['guarantees']);bizP(s,d,'6. Права, обязанности и ответственность','Стороны осуществляют права и исполняют обязанности, установленные Трудовым кодексом РФ и применимыми локальными актами. Изменение условий и прекращение договора производятся в установленном законом порядке.');s.ruled('Иные согласованные условия',d.additionalConditions,['additionalConditions'],16);blankRequisites(s,d);s.paragraph('Экземпляр трудового договора получил(а): __________________ / '+(d.buyer||'________________')+' / дата ________________.',['buyer']);}
function bizStaffRequest(s,d){const leave=DOC_NEW[d.type].kind==='leave';s.note('Кому: '+blankPartyValue(d,'seller'),9);s.mark(blankPartyKeys('seller',d.type),9,8,s.w-18,12);s.note('От: '+blankPartyValue(d,'buyer'),9);s.mark(blankPartyKeys('buyer',d.type),9,20,s.w-18,15);s.note('Должность: '+bizValue(d,'position')+'; подразделение: '+bizValue(d,'department'),9);s.mark(['position','department'],9,s.y-8,s.w-18,8);s.y+=5;s.center(leave?'ЗАЯВЛЕНИЕ НА ОТПУСК':'ЗАЯВЛЕНИЕ ОБ УВОЛЬНЕНИИ',13);if(leave){s.paragraph('Прошу предоставить '+bizValue(d,'leaveType').toLocaleLowerCase('ru-RU')+' отпуск с '+bizValue(d,'startDate')+' по '+bizValue(d,'endDate')+' продолжительностью '+bizValue(d,'leaveDays')+' календарных дней.',['leaveType','startDate','endDate','leaveDays']);if(d.reason)s.paragraph('Основание / пояснение: '+d.reason,['reason']);}else{s.paragraph('Прошу расторгнуть трудовой договор по моей инициативе (по собственному желанию). Дата увольнения: '+bizValue(d,'dismissalDate')+'.',['dismissalDate']);if(d.reason)s.paragraph('Дополнительные обстоятельства: '+d.reason,['reason']);if(d.attachments)s.ruled('Приложения',d.attachments,['attachments'],12);}s.y+=5;s.cells([blankCell(d,'date','Дата заявления'),{label:'Подпись работника / расшифровка',value:'____________________ / '+(d.buyer||'________________'),keys:['buyer','buyerSign']}],17);if(d.number){const y=s.y;s.note('Регистрационный № '+d.number,7);s.mark(['number'],9,y,s.w-18,s.y-y);}if(d.basis)s.ruled('Основание / связанный документ',d.basis,['basis'],10);}
function bizTimesheet(s,d){const month=bizMonth(d);bizStart(s,d,'ТАБЕЛЬ УЧЁТА РАБОЧЕГО ВРЕМЕНИ');s.note(docFormText(d.type)+' Отчётный месяц: '+String(month.month).padStart(2,'0')+'.'+month.year,7);s.mark(['reportMonth'],9,s.y-7,s.w-18,7);s.cells([blankPartyCell(d,'seller','Организация',false,3),blankCell(d,'okpo','Код ОКПО'),blankCell(d,'department','Подразделение')],14);const columns=[{label:'ФИО работника',width:43},{label:'Таб. №',width:13},...Array.from({length:month.days},(_,i)=>({label:String(i+1),width:6,size:5.5})),{label:'Дней',width:12},{label:'Часов',width:16}],rows=[];(d.timeEntries||[]).forEach((r,i)=>{const days=r.days||[],actual=days.slice(0,month.days),hours=Math.round(actual.reduce((n,x)=>n+docNum(x.hours),0)*100)/100,worked=actual.filter(x=>docNum(x.hours)>0).length;rows.push([{value:r.name,keys:['time:'+i+':name'],size:6.5},{value:r.personnel,keys:['time:'+i+':personnel'],size:6.5},...Array.from({length:month.days},(_,day)=>({value:days[day]?.code||'',keys:['time:'+i+':'+day+':code'],size:5.5})),{value:worked,size:6.5},{value:docCash(hours),size:6.5}]);rows.push([{value:'часы',size:6},{value:''},...Array.from({length:month.days},(_,day)=>({value:days[day]?.hours||'',keys:['time:'+i+':'+day+':hours'],size:5.5})),{value:''},{value:''}]);});s.table(columns,rows);s.note('Коды: Я — явка, В — выходной, ОТ — отпуск, Б — больничный. Иные коды применяются по принятой системе учёта. Итоги часов и отработанных дней рассчитаны по фактически введённым значениям.',7);s.cells([blankCell(d,'timekeeper','Ответственный за учёт: должность, подпись, ФИО'),blankCell(d,'departmentHead','Руководитель подразделения: подпись, ФИО'),blankCell(d,'hrOfficer','Работник кадровой службы: подпись, ФИО'),blankCell(d,'approvalDate','Дата подписания')],17);}
function bizSelf(s,d,act=false){const work=d.selfMode==='Работы',mode=work?'работ':'услуг';bizStart(s,d,act?(work?'АКТ СДАЧИ-ПРИЁМКИ РАБОТ САМОЗАНЯТОГО':'АКТ ОКАЗАННЫХ УСЛУГ САМОЗАНЯТОГО'):(work?'ДОГОВОР ПОДРЯДА С ПЛАТЕЛЬЩИКОМ НПД':'ДОГОВОР ОКАЗАНИЯ УСЛУГ С ПЛАТЕЛЬЩИКОМ НПД'));s.mark(['selfMode'],9,8,s.w-18,16);if(act){s.paragraph('По договору ГПХ № '+bizValue(d,'originalNumber')+' от '+bizValue(d,'originalDate')+' стороны оформили сдачу и приёмку '+mode+'.',['originalNumber','originalDate']);s.cells([blankPartyCell(d,'seller','Исполнитель — плательщик НПД'),blankPartyCell(d,'buyer','Заказчик')],18);s.cells([blankCell(d,'periodStart','Начало периода'),blankCell(d,'periodEnd','Окончание периода')],11);blankGoods(s,d);s.ruled('Сданный результат',d.result,['result'],16);s.ruled('Замечания / претензии',d.claims,['claims'],14);s.cells([blankCell(d,'receiptNumber','Номер чека «Мой налог»'),blankCell(d,'receiptDate','Дата чека'),blankCell(d,'receiptUrl','Ссылка / идентификатор чека')],13);s.note('Акт подтверждает приёмку результата. Расчёт подтверждается чеком, сформированным плательщиком НПД.',7);blankRequisites(s,d);return;}
 bizPartyPreamble(s,d);bizP(s,d,'1. Предмет договора',work?'Исполнитель обязуется выполнить согласованные работы и передать Заказчику их результат; Заказчик обязуется принять и оплатить результат.':'Исполнитель обязуется оказать согласованные услуги; Заказчик обязуется принять и оплатить их.');bizSubject(s,d,work?'Работы и передаваемый результат':'Состав и содержание услуг');s.title('2. Сроки и организация исполнения');bizDates(s,d);s.paragraph('Исполнитель самостоятельно определяет способы исполнения задания, не включается в штат Заказчика и не подчиняется правилам внутреннего трудового распорядка Заказчика. Настоящий договор не устанавливает трудовые отношения.',[]);s.ruled('Расходы, материалы и оборудование',d.expensesTerms,['expensesTerms'],14);bizP(s,d,'3. Приёмка результата','Сдача и приёмка '+mode+' оформляются актом. Порядок приёмки: '+bizValue(d,'acceptanceTerms')+'.',['acceptanceTerms']);s.title('4. Вознаграждение и расчёты');s.ruled('Вознаграждение за согласованный объём, руб.',d.amount,['amount'],11);s.paragraph('Порядок и сроки оплаты: '+bizValue(d,'paymentTerms')+'.',['paymentTerms']);s.title('5. Налог на профессиональный доход и чек');s.cells([blankCell(d,'npdProof','Сведения о постановке на учёт НПД'),blankCell(d,'npdCheckDate','Дата проверки статуса заказчиком')],13);s.paragraph('Исполнитель подтверждает применение НПД к доходам, которые отвечают требованиям законодательства. До оплаты Заказчик проверяет применимость режима к исполнителю и данным отношениям. Исполнитель формирует чек «Мой налог» по расчёту и передаёт его Заказчику в согласованном порядке: '+bizValue(d,'receiptTerms')+'.',['receiptTerms']);s.paragraph('При утрате права на НПД Исполнитель уведомляет Заказчика: '+bizValue(d,'statusLossNotice')+'. Налогообложение доходов определяется фактическим статусом и требованиями законодательства.',['statusLossNotice']);bizFinal(s,d,'6. Ответственность и заключительные условия');}
function bizAuto(s,d,act=false){bizStart(s,d,act?'АКТ ПРИЁМА-ПЕРЕДАЧИ АВТОМОБИЛЯ':'ДОГОВОР КУПЛИ-ПРОДАЖИ АВТОМОБИЛЯ');if(act)s.paragraph('К договору купли-продажи № '+bizValue(d,'originalNumber')+' от '+bizValue(d,'originalDate')+'.',['originalNumber','originalDate']);else bizPartyPreamble(s,d);s.title('1. Идентификация транспортного средства');s.cells([blankCell(d,'autoMake','Марка / модель',2),blankCell(d,'vin','Идентификационный номер VIN',2),blankCell(d,'autoYear','Год выпуска')],13);s.cells([blankCell(d,'autoCategory','Категория / тип ТС'),blankCell(d,'autoPlate','Регистрационный знак'),blankCell(d,'color','Цвет')],11);s.cells([blankCell(d,'bodyNumber','Номер кузова / шасси'),blankCell(d,'engineNumber','Модель / номер двигателя')],12);s.ruled('Паспорт транспортного средства / ЭПТС',d.pts,['pts'],13);s.ruled('Кем и когда выдан ПТС / ЭПТС',d.ptsIssued,['ptsIssued'],12);s.ruled('Свидетельство о регистрации ТС',d.sts,['sts'],13);s.ruled('Основание собственности продавца',d.ownershipProof,['ownershipProof'],12);if(!act){bizP(s,d,'2. Предмет и цена','Продавец передаёт указанный автомобиль в собственность Покупателя, а Покупатель принимает автомобиль и уплачивает согласованную цену '+docMoney(docNum(d.amount))+' ('+bizMoneyWords(d.amount)+'). НДС в цене: '+bizValue(d,'vat')+'.',['amount','vat']);s.ruled('Порядок расчётов / сведения об оплате',d.paymentTerms,['paymentTerms'],16);}else{s.cells([blankCell(d,'amount','Цена автомобиля по договору, руб.'),blankCell(d,'vat','НДС в цене'),blankCell(d,'paymentTerms','Сведения о расчётах')],14);}
 s.title(act?'2. Фактическая передача автомобиля':'3. Передача автомобиля и сведения о состоянии');s.cells([blankCell(d,'transferDate','Дата передачи'),blankCell(d,'transferPlace','Место передачи'),blankCell(d,'mileage','Пробег, км'),blankCell(d,'keysCount','Комплектов ключей')],12);s.ruled('Техническое состояние и известные дефекты',d.condition,['condition'],17);s.ruled('Комплектация и принадлежности',d.equipmentSet,['equipmentSet'],15);s.ruled('Передаваемые документы',d.documents,['documents'],13);s.ruled('Сведения об ограничениях, залоге и правах третьих лиц',d.encumbrances,['encumbrances'],16);if(act){s.paragraph('Передающая сторона передала, принимающая сторона приняла указанный автомобиль с перечисленными документами, ключами и принадлежностями.',['seller','buyer']);s.ruled('Замечания сторон',d.claims,['claims'],15);}else{s.paragraph('Передача автомобиля, ключей и документов оформляется актом. Стороны выполняют действия по регистрации транспортного средства в установленном законом порядке.',[]);}blankRequisites(s,d);}
function bizFreeUse(s,d){bizStart(s,d,'ДОГОВОР БЕЗВОЗМЕЗДНОГО ПОЛЬЗОВАНИЯ ИМУЩЕСТВОМ');bizPartyPreamble(s,d);bizP(s,d,'1. Предмет договора','Ссудодатель передаёт Ссудополучателю имущество во временное безвозмездное пользование. Ссудополучатель обязуется вернуть то же имущество с учётом нормального износа либо в ином согласованном состоянии.');s.ruled('Имущество и идентификаторы',d.objectDescription,['objectDescription'],17);bizPropertyTable(s,d);s.ruled('Основание прав ссудодателя',d.ownershipProof,['ownershipProof'],11);s.ruled('Состояние и комплектность',d.condition,['condition'],15);s.title('2. Сроки и использование');bizDates(s,d);s.ruled('Цель использования',d.purpose,['purpose'],12);s.paragraph('Передача и возврат оформляются актами. Плата за пользование имуществом не взимается.',[]);bizP(s,d,'3. Содержание и возврат','Содержание, ремонт и расходы: '+bizValue(d,'maintenance')+'. Порядок и срок возврата: '+bizValue(d,'returnTerms')+'.',['maintenance','returnTerms']);bizFinal(s,d,'4. Ответственность и заключительные условия');}
function bizBuild(s,d){switch(DOC_NEW[d.type].kind){case 'service':case 'supply':case 'sale':case 'work':bizContract(s,d);break;case 'premise':case 'equipment':bizLease(s,d);break;case 'addendum':case 'termination':bizAmend(s,d);break;case 'transfer':case 'return':bizTransfer(s,d);break;case 'power':bizPower(s,d);break;case 'proposal':case 'estimate':bizSales(s,d);break;case 'cashIn':bizCash(s,d,true);break;case 'cashOut':bizCash(s,d,false);break;case 'advance':bizAdvance(s,d);break;case 'receipt':bizReceipt(s,d);break;case 'loanReturn':bizReceipt(s,d,true);break;case 'loan':bizLoan(s,d);break;case 'claim':case 'refund':case 'guarantee':bizCorrespondence(s,d);break;case 'employment':bizEmployment(s,d);break;case 'leave':case 'resign':bizStaffRequest(s,d);break;case 'timesheet':bizTimesheet(s,d);break;case 'selfContract':bizSelf(s,d);break;case 'selfAct':bizSelf(s,d,true);break;case 'autoSale':bizAuto(s,d);break;case 'autoAct':bizAuto(s,d,true);break;case 'freeUse':bizFreeUse(s,d);break;default:throw Error('Нет печатного шаблона '+d.type);}}

