function bizItemLabel(r){return [r.subject,r.productCode?'Код: '+r.productCode:'',r.article?'Артикул: '+r.article:'',r.serialNumber?'Серийный / инвентарный №: '+r.serialNumber:'',r.condition?'Состояние: '+r.condition:''].filter(Boolean).join('; ');}
function bizItemUnit(r){return [r.unit,r.unitCode?'ОКЕИ '+r.unitCode:''].filter(Boolean).join(' / ');}
